import {verifyLocalReferenceLog} from '../../scripts/tp-reference-local.mjs';
import assert from 'node:assert/strict';
import {readFileSync,writeFileSync,mkdirSync} from 'node:fs';
import {resolve} from 'node:path';
import {execFileSync,spawnSync} from 'node:child_process';
import {pathToFileURL} from 'node:url';
import {verifyEvaluation,assertValueCellProductionExcluded} from '../../scripts/tp10-evaluation.mjs';
import {root,digest,inventory,nodesFromPlans,planInput,validateReceipt} from '../../scripts/provider-a1-receipts.mjs';
export const directory='docs/audit/evidence/tp10-20261011';
export const selectors=['scripts/tp-reference-local.mjs','third_party/valuecell/','engines/tests/test_tp10_valuecell_evaluation.py','scripts/tp10*','scripts/check-tp-intake.mjs','scripts/generate-build-manifest.mjs','Makefile','scripts/provider-a1-receipts.mjs','scripts/provider-a1-policy.json','docs/adr/20260731-tp10-valuecell-evaluation.md','docs/SumAlpha-QuantOS-Terminal-Frontend-Design-Spec.md'];
export const checks=[
 {id:'evaluation',command:['node','scripts/tp10-evaluation.mjs','--workspace'],marker:/TP10_EVALUATION_PASS/},
 {id:'upstream',command:['node','scripts/tp10-evaluation.mjs','--verify-upstream'],marker:/TP10_PINNED_PUBLIC_DIGESTS_PASS/},
 {id:'contract',command:['engines/.venv/bin/python','-m','pytest','engines/tests/test_tp10_valuecell_evaluation.py','-vv'],marker:/17 passed/},
 {id:'negatives',command:['node','--test','scripts/tp10-evaluation.test.mjs'],marker:/tests\s+49[\s\S]*?fail\s+0/},
 {id:'lint',command:['engines/.venv/bin/ruff','check','engines/tests/test_tp10_valuecell_evaluation.py'],marker:/All checks passed/},
 {id:'format',command:['engines/.venv/bin/ruff','format','--check','engines/tests/test_tp10_valuecell_evaluation.py'],marker:/1 file already formatted/},
 {id:'locks',command:['bash','scripts/check-lockfiles.sh'],marker:/All phase-1 locks parse and match their manifests/},
 {id:'intake',command:['node','scripts/check-tp-intake.mjs'],marker:/unapproved upstream packages are absent/},
];
export const localChecks=checks.map(c=>c.id==='upstream'?{id:'reference-local',command:['node','scripts/tp-reference-local.mjs','TP10'],marker:/LOCAL_REFERENCE_METADATA_PASS/}:c);
export const checksFor=r=>{assert(['UPSTREAM','LOCAL'].includes(r.validationMode??'UPSTREAM'));return r.validationMode==='LOCAL'?localChecks:checks;};
const excluded=['upstream source, assets, components, data/account schemas or runtime dependencies','implemented UI, browser usability or cross-platform acceptance','resolved upstream dependency graph or current CVE advisory clearance','third-party widget, market data, API or trading rights','production credentials, release, publication, hosted same-SHA CI or formal ACCEPTED'];
const deps=()=>nodesFromPlans().get('CORE:TP10').dependencies.map(nodeId=>{try{return{nodeId,...validateReceipt(nodeId)};}catch(e){return{nodeId,status:'BLOCKED',reason:e.message.split('\n')[0]};}});
export function verifyTp10(r,{checkDependencies=true,logDirectory=resolve(root,directory)}={}){
 assert.equal(r.schema,'quantos-tp10-development/v1');assert.equal(r.nodeId,'CORE:TP10');assert.equal(r.stage,'DEVELOPMENT');assert.equal(r.formalAccepted,false);assert.equal(r.engineeringStatus,'PASS');assert(['READY','BLOCKED'].includes(r.status));assert.deepEqual(r.excluded,excluded);assert.deepEqual(r.inputs,inventory(selectors),'TP10 functional inputs changed');assert.deepEqual(r.planInput,planInput(nodesFromPlans().get(r.nodeId)));assert(/^[a-f0-9]{40}$/.test(r.observedSourceCommit));assert(r.environment.node&&r.environment.python);assert.deepEqual(r.checks.map(c=>c.id),checksFor(r).map(c=>c.id));
 for(const [i,c]of r.checks.entries()){const spec=checksFor(r)[i];assert.deepEqual(c.command,spec.command);assert.equal(c.exitCode,0);assert.equal(c.status,'PASS');assert(Number.isFinite(Date.parse(c.executedAt))&&Date.parse(c.executedAt)<=Date.now());assert.equal(c.log,directory+'/'+spec.id+'.log');const bytes=readFileSync(resolve(logDirectory,spec.id+'.log'));assert.equal(digest(bytes),c.logSha256,'TP10 log changed');assert.match(bytes.toString(),spec.marker);}
 if(r.validationMode==='LOCAL'){assert.deepEqual(r.upstreamVerification,{status:'NOT_RUN',checkpoint:'RELEASE-GATE:BETA',externalExecution:false,currentPublicBytesVerified:false});verifyLocalReferenceLog(readFileSync(resolve(logDirectory,'reference-local.log'),'utf8'),'TP10');}else{const proof=JSON.parse(readFileSync(resolve(root,'third_party/valuecell/provenance.json')));const online=readFileSync(resolve(logDirectory,'upstream.log'),'utf8').split('\n').filter(l=>l.startsWith('{')).map(l=>JSON.parse(l));assert.deepEqual(online,proof.files.map(f=>({...f,retained:false})),'TP10 public observations differ');}
 verifyEvaluation();assertValueCellProductionExcluded([]);
 if(checkDependencies){assert.deepEqual(r.dependencies,deps());assert.equal(r.status,r.dependencies.every(d=>d.status==='READY')?'READY':'BLOCKED');if(r.status==='READY')validateReceipt('CORE:TP10');}
 return{engineeringStatus:'PASS',stageGate:checkDependencies?r.status:'NOT_ASSESSED',formalAccepted:false};
}
function record(local=false){const inputs=inventory(selectors);mkdirSync(resolve(root,directory),{recursive:true});const results=(local?localChecks:checks).map(spec=>{const executedAt=new Date().toISOString();const env=Object.fromEntries(Object.entries(process.env).filter(([k])=>!/DATABASE_URL|SUPABASE|PASSWORD|TOKEN|KEY|SECRET|QUANTOS_RUN_.*TESTS|QUANTOS_TRACE_EXPORT_PATH|QUANTOS_ENGINE/.test(k)));const run=spawnSync(spec.command[0],spec.command.slice(1),{cwd:root,encoding:'utf8',timeout:300000,maxBuffer:16*1024*1024,env});const output=(run.stdout??'')+(run.stderr??'');const log=directory+'/'+spec.id+'.log';writeFileSync(resolve(root,log),output);console.log(spec.id,run.status);return{id:spec.id,command:spec.command,executedAt,exitCode:run.status,status:run.status===0?'PASS':'FAIL',log,logSha256:digest(output)};});assert.deepEqual(inputs,inventory(selectors));const dependencies=deps();const r={schema:'quantos-tp10-development/v1',validationMode:local?'LOCAL':'UPSTREAM',...(local?{upstreamVerification:{status:'NOT_RUN',checkpoint:'RELEASE-GATE:BETA',externalExecution:false,currentPublicBytesVerified:false}}:{}),nodeId:'CORE:TP10',stage:'DEVELOPMENT',status:dependencies.every(d=>d.status==='READY')?'READY':'BLOCKED',engineeringStatus:results.every(c=>c.exitCode===0)?'PASS':'FAIL',formalAccepted:false,observedSourceCommit:execFileSync('git',['rev-parse','HEAD'],{encoding:'utf8'}).trim(),environment:{node:process.version,python:execFileSync('engines/.venv/bin/python',['--version'],{encoding:'utf8'}).trim()},planInput:planInput(nodesFromPlans().get('CORE:TP10')),inputs,checks:results,dependencies,excluded};writeFileSync(resolve(root,directory,'receipt.json'),JSON.stringify(r,null,2)+'\n');return verifyTp10(r,{checkDependencies:false});}
function admit(){const p=resolve(root,directory,'receipt.json'),r=JSON.parse(readFileSync(p));verifyTp10(r,{checkDependencies:false});validateReceipt('CORE:TP10');r.dependencies=deps();assert(r.dependencies.every(d=>d.status==='READY'));r.status='READY';writeFileSync(p,JSON.stringify(r,null,2)+'\n');return verifyTp10(r);}
if(process.argv[1]&&import.meta.url===pathToFileURL(resolve(process.argv[1])).href){try{assert(process.argv.length===3&&['--record','--record-local','--verify','--ready','--admit'].includes(process.argv[2]));const result=process.argv[2]==='--record'||process.argv[2]==='--record-local'?record(process.argv[2]==='--record-local'):process.argv[2]==='--admit'?admit():verifyTp10(JSON.parse(readFileSync(resolve(root,directory,'receipt.json'))));console.log(JSON.stringify(result));if(process.argv[2]==='--ready'&&result.stageGate!=='READY')process.exitCode=2;}catch(e){console.error(e.message.split('\n')[0]);process.exitCode=1;}}
